/**
 * Pure date and filter helpers for the public event list.
 *
 * Deliberately kept out of `lib/public-events.ts`, which pulls in the
 * Supabase admin client — this is the part client components need,
 * without the server baggage.
 *
 * All dates are `YYYY-MM-DD` strings, never Date objects across
 * boundaries. `new Date('2026-08-21')` is parsed as UTC midnight, which
 * lands on the wrong day in negative timezones — so we parse per part.
 */

/**
 * Sentinel for "no city filter". Lives here rather than in the grid component
 * so the server action behind the signup form can compare against the same value.
 */
export const ALL_CITIES = 'All'

export type TimeRange = 'all' | 'tonight' | 'this-weekend' | 'this-week' | 'this-month'

export const TIME_RANGES: Array<{ value: TimeRange; label: string }> = [
  { value: 'all', label: 'All' },
  { value: 'this-week', label: 'This week' },
]

/**
 * Today's date in Europe/Oslo as `YYYY-MM-DD`.
 *
 * The server runs UTC on Vercel, the browser runs local time. Without a
 * shared starting point, "Tonight" counts differently on the two sides
 * between midnight and 02:00, and React complains about a hydration
 * mismatch. So this is called on the server and passed down as a prop.
 *
 * The timezone stays Oslo regardless of interface language — the venues
 * are in Norway, so that is where a show date belongs.
 */
export function getOsloToday(now: Date = new Date()): string {
  // 'sv-SE' yields the ISO form YYYY-MM-DD directly.
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Oslo' }).format(now)
}

/** Parses `YYYY-MM-DD` into a local Date at midnight, with no UTC shift. */
export function parseIsoDate(value: string): Date {
  const [year, month, day] = value.slice(0, 10).split('-').map(Number)
  return new Date(year, (month ?? 1) - 1, day ?? 1)
}

/** The other way round: local Date to `YYYY-MM-DD`. */
export function toIsoDate(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${date.getFullYear()}-${month}-${day}`
}

function addDays(date: Date, days: number): Date {
  const next = new Date(date)
  next.setDate(next.getDate() + days)
  return next
}

/**
 * Start and end (inclusive) of a time range, as ISO dates.
 * Returns null for 'all'.
 *
 * The week runs Monday–Sunday. "This weekend" is the coming Friday to
 * Sunday — if it is already the weekend, that means this one, not the next.
 */
export function rangeBounds(range: TimeRange, today: string): { from: string; to: string } | null {
  if (range === 'all') return null

  const start = parseIsoDate(today)
  // getDay(): 0 = Sunday. We want 0 = Monday.
  const weekday = (start.getDay() + 6) % 7

  switch (range) {
    case 'tonight':
      return { from: today, to: today }

    case 'this-weekend': {
      // Friday = 4. Past Friday means the weekend is already under way.
      const daysToFriday = weekday <= 4 ? 4 - weekday : 0
      const friday = addDays(start, daysToFriday)
      const sunday = addDays(start, 6 - weekday)
      return { from: toIsoDate(friday > start ? friday : start), to: toIsoDate(sunday) }
    }

    case 'this-week':
      return { from: today, to: toIsoDate(addDays(start, 6 - weekday)) }

    case 'this-month': {
      const lastDay = new Date(start.getFullYear(), start.getMonth() + 1, 0)
      return { from: today, to: toIsoDate(lastDay) }
    }
  }
}

export function isInRange(showDate: string, range: TimeRange, today: string): boolean {
  const bounds = rangeBounds(range, today)
  if (!bounds) return true
  const date = showDate.slice(0, 10)
  return date >= bounds.from && date <= bounds.to
}

/**
 * "Today", "Tomorrow", otherwise "Wed 21 Aug" — used on the card's first
 * line, where date and time sit together.
 */
export function formatDayLabel(showDate: string, today: string): string {
  const date = showDate.slice(0, 10)
  if (date === today) return 'Today'
  if (date === toIsoDate(addDays(parseIsoDate(today), 1))) return 'Tomorrow'

  return new Intl.DateTimeFormat('en-GB', {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
  }).format(parseIsoDate(date))
}

lib/marketing/copy.ts.source:
/**
 * Teksten som følger med eksportfilene.
 *
 * Et Facebook-event er ikke bare et coverbilde — noen må skrive tittelen,
 * tidspunktet, stedet og lineupen inn i skjemaet. Den teksten kan vi lage
 * ferdig, slik at klubben limer inn i stedet for å skrive. Samme innhold i
 * kortere form er bildeteksten til SoMe-posten.
 *
 * Ingen Node-avhengigheter: både server og klient bruker den.
 */

const MONTHS_NB = [
  'januar', 'februar', 'mars', 'april', 'mai', 'juni',
  'juli', 'august', 'september', 'oktober', 'november', 'desember',
]

const WEEKDAYS_NB = ['søndag', 'mandag', 'tirsdag', 'onsdag', 'torsdag', 'fredag', 'lørdag']

export type MarketingCopyInput = {
  title: string
  date: string
  startTime: string | null
  doorsTime?: string | null
  venue: string | null
  city?: string | null
  description: string | null
  ticketUrl: string | null
  priceLabel: string | null
  lineup: Array<{ name: string; roleLabel: string | null }>
}

export function formatNorwegianDate(date: string): string {
  const parsed = new Date(`${date}T12:00:00`)
  if (Number.isNaN(parsed.getTime())) return date
  return `${WEEKDAYS_NB[parsed.getDay()]} ${parsed.getDate()}. ${MONTHS_NB[parsed.getMonth()]} ${parsed.getFullYear()}`
}

function timeLabel(startTime: string | null) {
  return startTime ? `kl. ${startTime.slice(0, 5)}` : null
}

/** Lang tekst — beskrivelsesfeltet på Facebook-eventet. */
export function facebookEventDescription(input: MarketingCopyInput): string {
  const headliners = input.lineup.filter((entry) => entry.roleLabel?.toLowerCase().includes('headliner'))
  const rest = input.lineup.filter((entry) => !headliners.includes(entry))

  return [
    input.description?.trim() || `${input.title} — en kveld med stand-up.`,
    '',
    'LINEUP',
    ...[...headliners, ...rest].map((entry) => (
      entry.roleLabel ? `• ${entry.name} (${entry.roleLabel})` : `• ${entry.name}`
    )),
    input.lineup.length === 0 ? '• Lineup annonseres snart' : null,
    '',
    'PRAKTISK',
    `• ${formatNorwegianDate(input.date)}${timeLabel(input.startTime) ? `, ${timeLabel(input.startTime)}` : ''}`,
    input.venue ? `• ${input.venue}${input.city ? `, ${input.city}` : ''}` : null,
    input.priceLabel ? `• Billetter fra ${input.priceLabel}` : null,
    '',
    input.ticketUrl ? `Billetter: ${input.ticketUrl}` : null,
  ]
    .filter((line) => line !== null)
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
}

/** Kort tekst — bildeteksten under SoMe-posten. */
export function socialCaption(input: MarketingCopyInput): string {
  const names = input.lineup.map((entry) => entry.name)
  const nameLine = names.length > 0
    ? names.length === 1 ? names[0] : `${names.slice(0, -1).join(', ')} og ${names[names.length - 1]}`
    : null

  return [
    `${input.title.toUpperCase()} 🎤`,
    nameLine,
    `${formatNorwegianDate(input.date)}${timeLabel(input.startTime) ? ` ${timeLabel(input.startTime)}` : ''}${input.venue ? ` · ${input.venue}` : ''}`,
    input.ticketUrl ? `Billetter i bio / ${input.ticketUrl}` : 'Billetter i bio',
  ]
    .filter(Boolean)
    .join('\n')
}

/** Tittelfeltet på Facebook-eventet. */
export function facebookEventTitle(input: MarketingCopyInput): string {
  const headliner = input.lineup.find((entry) => entry.roleLabel?.toLowerCase().includes('headliner'))
  return headliner ? `${input.title} — ${headliner.name}` : input.title
}

lib/marketing/palette.ts.source:
/**
 * Merkevarefargene et show markedsføres i.
 *
 * Klubben har allerede én farge (`clubs.brand_color`, hentet ut av logoen).
 * Plakater og eksportfiler trenger tre: en flatefarge, en mørk motvekt og en
 * aksent som løfter datoen og billettlenken. Denne fila utleder de tre fra én,
 * slik at «foreslå farger» alltid har noe å svare med — også for en klubb som
 * aldri har lastet opp en logo.
 *
 * Ingen Node-avhengigheter: både server og klient bruker den. Uthenting av
 * farger fra en bildefil ligger i `lib/marketing/palette-extract.ts`, som er
 * server-only fordi den bruker sharp.
 */

import {
  contrastRatio,
  ensureContrast,
  hslToRgb,
  normalizeBrandColor,
  parseHexColor,
  readableInkOn,
  rgbToHsl,
  toHexColor,
  type Rgb,
} from '@/lib/club-brand'
import type { MarketingPalette } from '@/types/database'

/** Tickethalo-oransje. Brukes når klubben verken har logo eller valgt farge. */
export const DEFAULT_MARKETING_SEED = '#ff5b24'

const SURFACE_DARK: Rgb = { r: 18, g: 14, b: 12 }

export const MARKETING_PALETTE_ROLES = [
  { key: 'primary', label: 'Primary', hint: 'Flatefarge — bakgrunn, bånd og knapper.' },
  { key: 'secondary', label: 'Secondary', hint: 'Mørk motvekt — tekstflater og dybde.' },
  { key: 'accent', label: 'Accent', hint: 'Blikkfang — dato, pris og billettlenke.' },
] as const satisfies ReadonlyArray<{ key: keyof MarketingPalette; label: string; hint: string }>

export function isHexColor(value: unknown): value is string {
  return typeof value === 'string' && parseHexColor(value) !== null
}

/** Normaliserer «#ABC», «abcdef» og liknende til «#aabbcc». */
export function normalizeHex(value: string | null | undefined, fallback: string): string {
  const parsed = parseHexColor(value)
  return parsed ? toHexColor(parsed) : fallback
}

/**
 * Bygger de tre fargene ut fra én frøfarge.
 *
 * Sekundærfargen er samme kulør trukket mot mørkt, slik at den leses som
 * «samme merkevare». Aksenten flyttes 150° rundt fargesirkelen — nok til å
 * skille seg fra primærfargen uten å bli det rene komplementet, som ofte
 * vibrerer stygt i trykk.
 */
export function paletteFromSeed(seed: string | null | undefined): MarketingPalette {
  const parsed = parseHexColor(seed) ?? parseHexColor(DEFAULT_MARKETING_SEED)!
  const primary = normalizeBrandColor(parsed)
  const { h, s } = rgbToHsl(primary)

  const secondary = hslToRgb({
    h: (h + 12) % 360,
    s: Math.min(0.9, Math.max(0.35, s * 0.85)),
    l: 0.16,
  })

  const accentBase = hslToRgb({
    h: (h + 150) % 360,
    s: Math.min(0.98, Math.max(0.6, s + 0.18)),
    l: 0.54,
  })

  return {
    primary: toHexColor(primary),
    secondary: toHexColor(secondary),
    accent: toHexColor(ensureContrast(accentBase, SURFACE_DARK, 3)),
  }
}

/**
 * Setter sammen en palett av farger som faktisk er plukket ut av et bilde.
 * Er det bare én brukbar farge, faller de to andre tilbake på utledningen.
 */
export function paletteFromColors(colors: string[]): MarketingPalette {
  const valid = colors.filter(isHexColor)
  if (valid.length === 0) return paletteFromSeed(DEFAULT_MARKETING_SEED)

  const derived = paletteFromSeed(valid[0])
  if (valid.length === 1) return derived

  // Den mørkeste brukbare fargen blir sekundær, den mest kulørte som ikke er
  // primærfargen blir aksent. Da speiler paletten bildet i stedet for regelen.
  const rgbs = valid.map((hex) => ({ hex, rgb: parseHexColor(hex)! }))
  const primary = rgbs[0]
  const rest = rgbs.slice(1)

  const darkest = [...rest].sort((a, b) => rgbToHsl(a.rgb).l - rgbToHsl(b.rgb).l)[0]
  const mostSaturated = [...rest]
    .filter((c) => c.hex !== darkest?.hex)
    .sort((a, b) => rgbToHsl(b.rgb).s - rgbToHsl(a.rgb).s)[0]

  const secondary = darkest && rgbToHsl(darkest.rgb).l < 0.42
    ? toHexColor(hslToRgb({ ...rgbToHsl(darkest.rgb), l: Math.min(0.22, rgbToHsl(darkest.rgb).l) }))
    : derived.secondary

  const accentCandidate = mostSaturated?.rgb
  const accent = accentCandidate && contrastRatio(accentCandidate, primary.rgb) > 1.6
    ? toHexColor(ensureContrast(accentCandidate, SURFACE_DARK, 3))
    : derived.accent

  return { primary: toHexColor(normalizeBrandColor(primary.rgb)), secondary, accent }
}

/** Leser en palett fra databasen. Ugyldige eller manglende felter fylles inn. */
export function resolvePalette(
  stored: unknown,
  clubBrandColor?: string | null,
): MarketingPalette {
  const fallback = paletteFromSeed(clubBrandColor ?? DEFAULT_MARKETING_SEED)
  if (!stored || typeof stored !== 'object') return fallback

  const raw = stored as Partial<Record<keyof MarketingPalette, unknown>>
  return {
    primary: normalizeHex(raw.primary as string, fallback.primary),
    secondary: normalizeHex(raw.secondary as string, fallback.secondary),
    accent: normalizeHex(raw.accent as string, fallback.accent),
  }
}

/** Tekstfargen som leser best oppå en av palettfargene. */
export function inkOn(hex: string): string {
  const parsed = parseHexColor(hex)
  return parsed ? toHexColor(readableInkOn(parsed)) : '#ffffff'
}

/** `rgba(...)`-variant, til hårfine bakgrunner i admin-flaten. */
export function tint(hex: string, alpha: number): string {
  const parsed = parseHexColor(hex)
  if (!parsed) return 'transparent'
  const { r, g, b } = parsed
  return `rgba(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)}, ${alpha})`
}

/** Palettens farger som en linje AI-en kan lese i plakatprompten. */
export function palettePromptLine(palette: MarketingPalette): string {
  return [
    `Primary surface colour ${palette.primary}`,
    `secondary/dark colour ${palette.secondary}`,
    `accent colour ${palette.accent} for date, price and ticket call-to-action`,
  ].join(', ')
}

lib/marketing/slots.ts.source:
/**
 * Bilderutene i malen, matchet mot bookingene.
 *
 * En mal med sju ruter skal ikke fylles i den rekkefølgen artistene tilfeldigvis
 * takket ja. Rutene er rangert som på en plakat — headlineren først, så
 * konferansieren, så resten i lineup-rekkefølge — og bookingene legges inn i
 * samme rangering. Ruten merket «Headliner» får dermed headlinerens bilde uten
 * at noen har dratt noe noe sted.
 *
 * Klubben kan alltid overstyre: `show_marketing_slots` er lagrede valg, og de
 * vinner over den automatiske matchingen.
 *
 * Ingen Node-avhengigheter: både server og klient bruker den.
 */

import { normalizeArtistRole } from '@/lib/artist-roles'

/** Lav verdi = høyt på plakaten. */
const ROLE_RANK: Record<string, number> = {
  headliner: 0,
  konferansier: 1,
  'stand-up': 2,
  'open mic': 3,
}

export type SlotRequirement = {
  id: string
  role_name: string
  quantity: number
  lineup_position: number
}

export type SlotSpot = {
  artist_id: string
  show_requirement_id: string
  status: string
}

export type SlotArtist = {
  id: string
  full_name: string
  stage_name: string | null
  profile_image_url: string | null
}

/** Et lagret valg fra `show_marketing_slots`. */
export type StoredSlot = {
  slot_index: number
  artist_id: string | null
  image_url: string | null
}

export type MarketingSlot = {
  slotIndex: number
  /** «Headliner», «Stand-up 2» — teksten som står ved ruten i malen. */
  roleLabel: string
  /** Hvilken booking ruten kommer fra. Null = tom rute i malen. */
  artistId: string | null
  artistName: string | null
  /** Bildet ruten faktisk bruker: overstyringen, ellers profilbildet. */
  imageUrl: string | null
  /** Artistens eget profilbilde, uavhengig av overstyring. */
  profileImageUrl: string | null
  /** True når klubben har lastet opp et eget bilde til ruten. */
  hasCustomImage: boolean
  /** True når ruten er satt for hånd i stedet for automatisk. */
  isManual: boolean
}

const ACTIVE_SPOT_STATUSES = new Set(['confirmed', 'completed', 'paid'])

export function artistDisplayName(artist: SlotArtist | undefined | null): string {
  if (!artist) return 'Unknown artist'
  return artist.stage_name ?? artist.full_name
}

/**
 * Rangerer bookingene slik en plakat leser dem: rolle først, så posisjon.
 * Rekkefølgen er stabil, så en ny artist på en støttespot flytter ikke
 * headlinerens bilde.
 */
function rankRequirements(requirements: SlotRequirement[]): SlotRequirement[] {
  return [...requirements].sort((a, b) => {
    const rankA = ROLE_RANK[normalizeArtistRole(a.role_name) ?? ''] ?? 9
    const rankB = ROLE_RANK[normalizeArtistRole(b.role_name) ?? ''] ?? 9
    if (rankA !== rankB) return rankA - rankB
    if (a.lineup_position !== b.lineup_position) return a.lineup_position - b.lineup_position
    return a.id.localeCompare(b.id)
  })
}

function slotLabel(roleName: string, indexWithinRole: number, totalForRole: number): string {
  const canonical = normalizeArtistRole(roleName)
  const base = canonical === 'headliner' ? 'Headliner'
    : canonical === 'konferansier' ? 'Host'
    : canonical === 'stand-up' ? 'Stand-up'
    : canonical === 'open mic' ? 'Open Mic'
    : roleName
  return totalForRole > 1 ? `${base} ${indexWithinRole + 1}` : base
}

/**
 * Bygger ruteplanen for showet.
 *
 * `templateSlotCount` er antall ruter i den valgte malen. Har malen flere ruter
 * enn showet har artister, blir de siste tomme — det er informasjon klubben
 * trenger, ikke noe vi skal skjule.
 */
export function buildMarketingSlots(input: {
  requirements: SlotRequirement[]
  spots: SlotSpot[]
  artists: SlotArtist[]
  stored?: StoredSlot[]
  templateSlotCount?: number | null
}): MarketingSlot[] {
  const artistById = new Map(input.artists.map((artist) => [artist.id, artist]))
  const storedByIndex = new Map((input.stored ?? []).map((slot) => [slot.slot_index, slot]))
  const activeSpots = input.spots.filter((spot) => ACTIVE_SPOT_STATUSES.has(spot.status))

  const spotsByRequirement = new Map<string, SlotSpot[]>()
  for (const spot of activeSpots) {
    const bucket = spotsByRequirement.get(spot.show_requirement_id)
    if (bucket) bucket.push(spot)
    else spotsByRequirement.set(spot.show_requirement_id, [spot])
  }

  const planned: Array<{ roleLabel: string; artistId: string | null }> = []
  for (const requirement of rankRequirements(input.requirements)) {
    const filled = spotsByRequirement.get(requirement.id) ?? []
    const total = Math.max(requirement.quantity, filled.length)
    for (let index = 0; index < total; index++) {
      planned.push({
        roleLabel: slotLabel(requirement.role_name, index, total),
        artistId: filled[index]?.artist_id ?? null,
      })
    }
  }

  // Artister som er bekreftet på et krav som er slettet siden, skal ikke
  // forsvinne fra plakaten bare fordi kravet gjorde det.
  const plannedArtistIds = new Set(planned.map((slot) => slot.artistId).filter(Boolean))
  for (const spot of activeSpots) {
    if (plannedArtistIds.has(spot.artist_id)) continue
    plannedArtistIds.add(spot.artist_id)
    planned.push({ roleLabel: 'Stand-up', artistId: spot.artist_id })
  }

  const slotCount = Math.max(planned.length, input.templateSlotCount ?? 0, storedByIndex.size)

  return Array.from({ length: slotCount }, (_, index) => {
    const slotIndex = index + 1
    const auto = planned[index] ?? { roleLabel: `Slot ${slotIndex}`, artistId: null }
    const stored = storedByIndex.get(slotIndex)

    // `artist_id: null` på en lagret rad er et bevisst «la ruten stå tom»,
    // og skal ikke falle tilbake på den automatiske matchen.
    const isManual = stored !== undefined
    const artistId = isManual ? stored.artist_id : auto.artistId
    const artist = artistId ? artistById.get(artistId) : undefined
    const customImage = stored?.image_url ?? null

    return {
      slotIndex,
      roleLabel: auto.roleLabel,
      artistId: artistId ?? null,
      artistName: artist ? artistDisplayName(artist) : null,
      imageUrl: customImage ?? artist?.profile_image_url ?? null,
      profileImageUrl: artist?.profile_image_url ?? null,
      hasCustomImage: Boolean(customImage),
      isManual,
    }
  })
}

/**
 * Hvor godt en mal passer lineupen.
 *
 * En mal uten oppgitt rutetall («0») kan brukes til alt, men skal ikke stå
 * øverst i lista foran en mal som faktisk har riktig antall ruter.
 */
export function templateFit(slotCount: number, lineupSize: number): {
  score: number
  label: string
  tone: 'exact' | 'close' | 'unknown' | 'off'
} {
  if (!slotCount) return { score: 2, label: 'Slot count unknown', tone: 'unknown' }
  if (slotCount === lineupSize) return { score: 0, label: `${slotCount} slots — exact fit`, tone: 'exact' }

  const diff = Math.abs(slotCount - lineupSize)
  if (diff <= 1) {
    return {
      score: 1,
      label: slotCount > lineupSize ? `${slotCount} slots — one stays empty` : `${slotCount} slots — one artist won't fit`,
      tone: 'close',
    }
  }

  return { score: 3 + diff, label: `${slotCount} slots`, tone: 'off' }
}

/** Rutene AI-en faktisk kan tegne — de som har både artist og bilde. */
export function usableSlots(slots: MarketingSlot[]): MarketingSlot[] {
  return slots.filter((slot) => slot.artistId && slot.imageUrl)
}

